use super::*;

// ============================================================
// ISO 9660 integration tests (bsdtar-written fixtures)
// ============================================================
//
// Reference images generated by libarchive's ISO9660 writer
// (`bsdtar -cf out.iso --format iso9660`), committed under
// `tests/fixtures/iso9660/`:
//   - bsdtar-plain.iso:      plain ISO9660 (uppercase names, `;1` versions)
//   - bsdtar-rockridge.iso:  Rock Ridge 1.12 + SUSP 1.10 extensions
//   - bsdtar-joliet.iso:     Joliet supplementary volume descriptor
//   - bsdtar-eltorito.iso:   El Torito boot record + catalog + boot.img
// Source tree: iso-tree/{hello.txt(14B), bigfile.dat(3000B),
// sub/{one.dat(1B), deep/two.dat(1B)}, link.txt -> hello.txt}.

const PLAIN: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-plain.iso");
const RR: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-rockridge.iso");
const JOLIET: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-joliet.iso");

fn find<'a>(img: &'a iso9660::decode::IsoImage, path: &str) -> &'a iso9660::decode::IsoEntry {
    img.entries
        .iter()
        .find(|e| e.name == path)
        .unwrap_or_else(|| panic!("missing entry {path}"))
}

#[test]
fn test_iso9660_plain_image() {
    let img = iso9660::decode::decode(PLAIN).unwrap();
    assert_eq!(img.volume_id, "CDROM");
    assert!(!img.has_rock_ridge);
    // bsdtar emits a Joliet SVD even for the default writer;
    // plain names win only when no usable alternate tree exists.
    let hello = find(&img, "ISO_TREE/HELLO.TXT");
    assert_eq!(hello.kind, iso9660::decode::IsoKind::File);
    assert_eq!(hello.data.len(), 14);
    // directory names also lose the `;version` suffix
    let sub = find(&img, "ISO_TREE/SUB");
    assert_eq!(sub.kind, iso9660::decode::IsoKind::Directory);
    let two = find(&img, "ISO_TREE/SUB/DEEP/TWO.DAT");
    assert_eq!(two.data.len(), 1);
    // no '.'/'..' pseudo entries
    assert!(img.entries.iter().all(|e| e.name != "." && e.name != ".."));
}

#[test]
fn test_iso9660_rockridge_image() {
    let img = iso9660::decode::decode(RR).unwrap();
    assert!(img.has_rock_ridge);

    // NM names: lowercase POSIX names from the Rock Ridge tree
    let hello = find(&img, "iso-tree/hello.txt");
    assert_eq!(hello.kind, iso9660::decode::IsoKind::File);
    assert_eq!(hello.data, b"hello iso9660\n");

    // multi-sector file (3000 bytes crosses a 2048 boundary)
    let big = find(&img, "iso-tree/bigfile.dat");
    assert_eq!(big.data.len(), 3000);
    assert!(big.data.iter().any(|&b| b != 0));

    // nested directories
    let deep = find(&img, "iso-tree/sub/deep/two.dat");
    assert_eq!(deep.data.len(), 1);

    // PX entries carry POSIX modes (444 file / 555 dir on RO media)
    let sub = find(&img, "iso-tree/sub");
    assert_eq!(sub.mode & 0o170000, 0o040000);
    assert_eq!(sub.mode & 0o111, 0o111);
    assert_eq!(hello.mode & 0o170000, 0o100000);

    // SL symlink: target recorded as entry data
    let link = find(&img, "iso-tree/link.txt");
    assert_eq!(link.kind, iso9660::decode::IsoKind::Symlink);
    assert_eq!(link.data, b"hello.txt");
}

#[test]
fn test_iso9660_joliet_image() {
    let img = iso9660::decode::decode(JOLIET).unwrap();
    assert!(img.has_joliet);
    // Joliet UCS-2 names keep the original casing
    let hello = find(&img, "iso-tree/hello.txt");
    assert_eq!(hello.data, b"hello iso9660\n");
    let deep = find(&img, "iso-tree/sub/deep/two.dat");
    assert_eq!(deep.data.len(), 1);
    let big = find(&img, "iso-tree/bigfile.dat");
    assert_eq!(big.data.len(), 3000);
}

#[test]
fn test_iso9660_path_table() {
    // All three bsdtar fixtures carry the same 4-entry type-L path
    // table (ECMA-119 §9.4): root + ISO_TREE + SUB + DEEP.
    for bytes in [PLAIN, RR, JOLIET] {
        let img = iso9660::decode::decode(bytes).unwrap();
        let pt = &img.path_table;
        assert_eq!(pt.len(), 4);
        // record 1 is the root, self-parented, identifier 0x00
        assert_eq!(pt[0].name, [0]);
        assert_eq!(pt[0].parent, 1);
        let names: Vec<&[u8]> = pt[1..].iter().map(|e| e.name.as_slice()).collect();
        assert_eq!(
            names,
            [
                b"ISO_TREE".as_slice(),
                b"SUB".as_slice(),
                b"DEEP".as_slice()
            ]
        );
        assert_eq!((pt[1].parent, pt[2].parent, pt[3].parent), (1, 2, 3));
        // parent indices always point at an earlier record
        for (i, e) in pt.iter().enumerate().skip(1) {
            assert!((e.parent as usize) <= i, "entry {i} parent out of range");
        }
        // each extent names a directory whose "." record points
        // back at the same extent (cross-check vs. the tree walk)
        for e in pt {
            let off = e.extent as usize * 2048;
            let rec = &bytes[off..off + 34];
            assert_eq!(u32::from_le_bytes(rec[2..6].try_into().unwrap()), e.extent);
            assert_eq!(u32::from_be_bytes(rec[6..10].try_into().unwrap()), e.extent);
            assert_eq!(rec[25] & 0x02, 0x02, "path table extent is not a directory");
            assert_eq!(rec[32], 1, "first record is not \".\"");
        }
    }
    // path table directory names match the walked directory tree
    // (primary-tree d-characters, same set as entry leaf names)
    let img = iso9660::decode::decode(PLAIN).unwrap();
    let mut walked: Vec<&str> = img
        .entries
        .iter()
        .filter(|e| e.kind == iso9660::decode::IsoKind::Directory)
        .map(|e| e.name.rsplit('/').next().unwrap())
        .collect();
    walked.sort_unstable();
    let mut table: Vec<&[u8]> = img.path_table[1..]
        .iter()
        .map(|e| e.name.as_slice())
        .collect();
    table.sort_unstable();
    assert_eq!(
        table,
        walked.iter().map(|s| s.as_bytes()).collect::<Vec<&[u8]>>()
    );
}

#[test]
fn test_iso9660_pvd_metadata() {
    // bsdtar writes system id "LINUX", application id
    // "LIBARCHIVE <version>", creation/modification/effective
    // timestamps, and leaves the expiration field unspecified.
    let img = iso9660::decode::decode(PLAIN).unwrap();
    let m = &img.meta;
    assert_eq!(m.system_id, "LINUX");
    assert!(m.application_id.starts_with("LIBARCHIVE "));
    assert_eq!(m.creation_time, Some(1790617411)); // 2026-09-28 17:43:31 GMT
    assert_eq!(m.modification_time, m.creation_time);
    assert_eq!(m.effective_time, m.creation_time);
    assert_eq!(m.expiration_time, None);

    // the Joliet fixture's SVD carries the same fields as UCS-2BE
    let img = iso9660::decode::decode(JOLIET).unwrap();
    let jm = img.joliet_meta.expect("joliet meta");
    assert_eq!(jm.system_id, "Linux");
    assert!(jm.application_id.starts_with("libarchive "));
    assert_eq!(jm.creation_time, img.meta.creation_time);
    assert_eq!(jm.expiration_time, None);
}

#[test]
fn test_iso9660_codec_trait() {
    use archive::traits::{ArchiveDecode, ArchiveEntry};
    let codec = iso9660::Iso9660Codec;
    let entries = codec.decode(RR).unwrap();
    assert!(entries.iter().any(|e| e.name() == "iso-tree/hello.txt"));
}

#[test]
fn test_iso9660_rejects_truncated() {
    // shorter than the PVD sector
    assert!(iso9660::decode::decode(&RR[..16 * 2048]).is_err());
    // truncate inside referenced file data (the image uses sectors
    // up to ~32; cutting at sector 30 drops extent payload)
    assert!(iso9660::decode::decode(&RR[..30 * 2048]).is_err());
    // empty input
    assert!(iso9660::decode::decode(&[]).is_err());
}

#[test]
fn test_iso9660_rejects_corrupt() {
    // PVD magic corrupt
    let mut img = RR.to_vec();
    img[16 * 2048 + 1] = b'X';
    assert!(iso9660::decode::decode(&img).is_err());
    // duplicate PVD: point the terminator at a copy of the PVD
    let mut img = RR.to_vec();
    let pvd = img[16 * 2048..17 * 2048].to_vec();
    // find first terminator sector and overwrite
    for s in 17..img.len() / 2048 {
        if img[s * 2048] == 255 {
            img[s * 2048..(s + 1) * 2048].copy_from_slice(&pvd);
            break;
        }
    }
    assert!(iso9660::decode::decode(&img).is_err());
}

const ELTORITO: &[u8] = include_bytes!("../fixtures/iso9660/bsdtar-eltorito.iso");

// bsdtar El Torito image: -o boot=boot.img -o boot-catalog=bootcat.bin
// over a tree containing boot.img ("BOOTPAYLOAD" + pad) and hello.txt.
#[test]
fn test_iso9660_eltorito_image() {
    let img = iso9660::decode::decode(ELTORITO).unwrap();
    assert_eq!(img.el_torito.len(), 1);
    let et = &img.el_torito[0];
    assert_eq!(et.platform, 0); // x86
    assert_eq!(et.entries.len(), 1);
    let e = &et.entries[0];
    assert!(e.bootable);
    assert_eq!(e.media_type, 0); // no-emulation
    assert_eq!(e.sector_count, 4); // 4 * 512 = 2048 bytes
    assert_eq!(e.image.len(), 2048);
    assert!(e.image.starts_with(b"BOOTPAYLOAD"));
}

// ============================================================
// ISO 9660 encoder tests
// ============================================================

#[test]
fn test_iso9660_encoder_roundtrip() {
    let mut enc = iso9660::encode::IsoEncoder::new().with_volume_name("encvol");
    enc.add_file("hello.txt", b"hello encoder");
    enc.add_file("sub/deep/two.dat", b"xy");
    enc.add_directory("empty");
    let img = enc.finish().unwrap();
    let dec = iso9660::decode::decode(&img).unwrap();
    assert_eq!(dec.volume_id, "ENCVOL");
    assert!(!dec.has_rock_ridge);
    assert_eq!(find(&dec, "HELLO.TXT").data, b"hello encoder");
    assert_eq!(find(&dec, "SUB/DEEP/TWO.DAT").data, b"xy");
    assert_eq!(dec.path_table.len(), 4);
}

#[test]
fn test_iso9660_encoder_rockridge() {
    let mut enc = iso9660::encode::IsoEncoder::new().with_rock_ridge();
    enc.add_file("iso-tree/hello.txt", b"hello iso9660\n");
    enc.add_symlink("iso-tree/link.txt", "hello.txt");
    let img = enc.finish().unwrap();
    let dec = iso9660::decode::decode(&img).unwrap();
    assert!(dec.has_rock_ridge);
    assert_eq!(find(&dec, "iso-tree/hello.txt").data, b"hello iso9660\n");
    let link = find(&dec, "iso-tree/link.txt");
    assert_eq!(link.kind, iso9660::decode::IsoKind::Symlink);
    assert_eq!(link.data, b"hello.txt");
}

#[test]
fn test_iso9660_encoder_trait() {
    use archive::traits::{ArchiveDecode, ArchiveEncode, ArchiveEntry};
    let mut enc = iso9660::Iso9660ArchiveEncoder::new();
    enc.add_file("t.txt", b"trait");
    let img = enc.finish().unwrap();
    let entries = iso9660::Iso9660Codec.decode(&img).unwrap();
    assert_eq!(entries.len(), 1);
    assert_eq!(entries[0].name(), "T.TXT");
    assert_eq!(entries[0].data(), b"trait");
}

/// bsdtar (libarchive ISO9660 reader) lists a Rock Ridge image the
/// encoder produced; skipped when the tool is not installed.
#[test]
fn test_iso9660_encoder_bsdtar_oracle() {
    use std::process::Command;
    use std::time::{SystemTime, UNIX_EPOCH};

    if Command::new("bsdtar").arg("--version").output().is_err() {
        return;
    }
    let mut enc = iso9660::encode::IsoEncoder::new().with_rock_ridge();
    enc.add_file("iso-tree/hello.txt", b"hello iso9660\n");
    enc.add_file("iso-tree/sub/deep/two.dat", b"2");
    enc.add_symlink("iso-tree/link.txt", "hello.txt");
    let img = enc.finish().unwrap();

    let uniq = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let dir = std::env::temp_dir().join(format!("archive_test_iso9660_{uniq}"));
    std::fs::create_dir_all(&dir).unwrap();
    let image_path = dir.join("enc.iso");
    std::fs::write(&image_path, &img).unwrap();
    let output = Command::new("bsdtar")
        .arg("-tf")
        .arg(&image_path)
        .output()
        .unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    assert!(
        output.status.success(),
        "bsdtar rejected encoder output: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let list = String::from_utf8_lossy(&output.stdout);
    for name in [
        "iso-tree/hello.txt",
        "iso-tree/sub/deep/two.dat",
        "iso-tree/link.txt",
    ] {
        assert!(list.contains(name), "missing {name} in bsdtar -tf: {list}");
    }
}
